import java.util.Calendar;
import java.util.Date;
import java.util.GregorianCalendar;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TimeZone;
import org.apache.commons.lang3.Validate;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class FastDateFormat_format_TriageGen3Test {

    @Test
    public void testFormatWithSimplePattern() {
        String pattern = "yyyy-MM-dd";
        FastDateFormat fdf = FastDateFormat.getInstance(pattern);

        // Set a specific date: 2023-10-27 10:00:00 UTC
        Calendar cal = Calendar.getInstance(TimeZone.getTimeZone("UTC"));
        cal.set(2023, Calendar.OCTOBER, 27, 10, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        Date date = cal.getTime();

        String result = fdf.format(date);
        assertEquals("2023-10-27", result);
    }

    @Test
    public void testFormatWithTimeZone() {
        String pattern = "HH:mm";
        TimeZone tz = TimeZone.getTimeZone("GMT+8");
        FastDateFormat fdf = FastDateFormat.getInstance(pattern, tz);

        // 10:00 UTC should be 18:00 GMT+8
        Calendar cal = Calendar.getInstance(TimeZone.getTimeZone("UTC"));
        cal.set(2023, Calendar.OCTOBER, 27, 10, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        Date date = cal.getTime();

        String result = fdf.format(date);
        assertEquals("18:00", result);
    }

    @Test
    public void testFormatWithLocale() {
        String pattern = "MMMM";
        Locale locale = Locale.FRENCH;
        FastDateFormat fdf = FastDateFormat.getInstance(pattern, Locale.getDefault(), locale);

        Calendar cal = Calendar.getInstance();
        cal.set(2023, Calendar.OCTOBER, 1);
        Date date = cal.getTime();

        String result = fdf.format(date);
        // October in French is "octobre"
        assertEquals("octobre", result.toLowerCase());
    }

    @Test
    public void testFormatWithDateTimeInstance() {
        // Using the pre-defined styles
        FastDateFormat fdf = FastDateFormat.getDateTimeInstance(Calendar.SHORT, Calendar.SHORT);
        Date date = new Date();

        String result = fdf.format(date);
        assertNotNull(result);
        // Ensure it's not empty and contains reasonable length for a date-time string
        assert(result.length() > 0);
    }

    @Test
    public void testFormatWithFullInstance() {
        FastDateFormat fdf = FastDateFormat.getDateTimeInstance(
                Calendar.LONG, 
                Calendar.LONG, 
                TimeZone.getTimeZone("UTC"), 
                Locale.US
        );

        Calendar cal = Calendar.getInstance(TimeZone.getTimeZone("UTC"));
        cal.set(2023, Calendar.JANUARY, 1, 12, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        Date date = cal.getTime();

        String result = fdf.format(date);
        // Expected format: January 1, 2023 12:00:00 PM (depending on exact JDK implementation of LONG)
        assertNotNull(result);
        assert(result.contains("2023"));
    }

    @Test
    public void testFormatWithComplexPattern() {
        String pattern = "yyyy/MM/dd HH:mm:ss.SSS";
        FastDateFormat fdf = FastDateFormat.getInstance(pattern);

        Calendar cal = Calendar.getInstance();
        cal.set(2023, Calendar.DECEMBER, 31, 23, 59, 59);
        cal.set(Calendar.MILLISECOND, 999);
        Date date = cal.getTime();

        String result = fdf.format(date);
        // Pattern check via substring to avoid flakey tests on exact spacing/leading zeros in different envs
        assert(result.contains("2023/12/31"));
        assert(result.contains("23:59:59"));
    }

    @Test
    public void testFormatWithNullDateThrowsException() {
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy");
        try {
            fdf.format(null);
            org.junit.Assert.fail("Should have thrown NullPointerException");
        } catch (NullPointerException e) {
            // Expected
        }
    }
}
